#!/bin/bash
# Run this script to set GitHub Secrets
# Requires: gh CLI authenticated

echo "Setting GitHub Secrets for notes-app..."

# The keystore (base64 encoded)
echo "" | gh secret set SIGNING_KEY --repo Free4Agent/notes-app

# Other secrets
echo "notesapp" | gh secret set ALIAS --repo Free4Agent/notes-app
echo "NotesApp2024Secure" | gh secret set KEY_STORE_PASSWORD --repo Free4Agent/notes-app
echo "NotesApp2024Secure" | gh secret set KEY_PASSWORD --repo Free4Agent/notes-app

echo "Secrets set successfully!"
